contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function f(address r1, address r2) public {
        require(r1 != address(this) && r2 != address(this) && r1 != r2);

        // First call succeeds because this contract is the owner of c.
        c.sendTo(r1, 0); if (__ESBMC_reverted()) return;

        // In P the owner is unchanged, so this second call must also succeed.
        // In M the first call set owner = r1, so this second call reverts.
        bool ok2 = true;
        c.sendTo(r2, 0); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            ok2 = false;
        } else {
            ok2 = true;
        }

        assert(ok2);
    }
}

